// Compatta le email in un unico testo per l'AI
const righe = [];

for (const item of $input.all()) {
  const e = item.json;
  const da = e.from?.value?.[0]?.name || e.from?.value?.[0]?.address || e.From || 'Sconosciuto';
  const oggetto = e.subject || e.Subject || '(senza oggetto)';
  const anteprima = String(e.snippet || e.text || '').slice(0, 200).replace(/\s+/g, ' ');
  righe.push(`DA: ${da}\nOGGETTO: ${oggetto}\nANTEPRIMA: ${anteprima}\n---`);
}

if (righe.length === 0) {
  return [{ json: { vuoto: true, testoEmail: '' } }];
}

return [{ json: { vuoto: false, totale: righe.length, testoEmail: righe.join('\n') } }];
